contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _value, bool callerIsOwner) public payable {
        require(callerIsOwner == (msg.sender == c.owner()), "caller flag must match actual caller");
        uint beforeBalance = address(c).balance;
        bool reverted;
        c.withdraw(_value); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        uint afterBalance = address(c).balance;
        assert(
            (reverted && afterBalance == beforeBalance) ||
            (!reverted && beforeBalance >= _value && afterBalance == beforeBalance - _value)
        );
    }

    receive() external payable {}
}

