// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 _value, bool callerIsOwner) internal {
        callerIsOwner = (msg.sender == c.owner());
        uint beforeBalance = address(c).balance;
        bool reverted;
        try c.withdraw(_value) { reverted = false; } catch { reverted = true; }
        uint afterBalance = address(c).balance;
        assertTrue((reverted && afterBalance == beforeBalance) ||
            (!reverted && beforeBalance >= _value && afterBalance == beforeBalance - _value));
    }

    function testFuzz_run(uint256 _value, bool callerIsOwner) public {
        _run(_value, callerIsOwner);
    }

    receive() external payable {}
}
